"""Updates from GitHub releases: list the versions, install any of them (newer or older), and check
for a newer one by itself. Installing = download that tag's source and run its install.sh."""
import json
import re
import shutil
import subprocess
import tarfile
import tempfile
import urllib.request
from pathlib import Path

from .version import REPO, VERSION


def _get(url):
    req = urllib.request.Request(url, headers={"User-Agent": "fbt-calibrator"})
    return urllib.request.urlopen(req, timeout=20)


def _num(s):
    return [int(x) for x in re.findall(r"\d+", s)]


def newer(a, b):
    """Is version a newer than version b ("v1.3.0" vs "1.2.1")?"""
    return _num(a) > _num(b)


def releases():
    """Published versions, newest first: [{tag, version, date, notes}] (no drafts or pre-releases)."""
    with _get(f"https://api.github.com/repos/{REPO}/releases?per_page=30") as r:
        data = json.load(r)
    out = []
    for rel in data:
        if rel.get("draft") or rel.get("prerelease") or not rel.get("tag_name"):
            continue
        out.append({"tag": rel["tag_name"], "version": rel["tag_name"].lstrip("v"),
                    "date": (rel.get("published_at") or "")[:10],
                    "notes": (rel.get("body") or "").strip()})
    out.sort(key=lambda r: _num(r["version"]), reverse=True)
    return out


def newest_if_newer(rels):
    """The newest release when it is newer than the running one, else None."""
    return rels[0] if rels and newer(rels[0]["version"], VERSION) else None


def install(tag):
    """Download the release `tag` and install it over this one (the calibration is kept)."""
    with tempfile.TemporaryDirectory() as tmp:
        archive = Path(tmp) / "src.tar.gz"
        with _get(f"https://codeload.github.com/{REPO}/tar.gz/refs/tags/{tag}") as r, open(archive, "wb") as out:
            shutil.copyfileobj(r, out)
        with tarfile.open(archive) as t:
            t.extractall(tmp, filter="data")
        src = next(p for p in Path(tmp).iterdir() if p.is_dir())
        res = subprocess.run(["bash", str(src / "install.sh"), "--no-restart"], capture_output=True, text=True)
        if res.returncode:
            raise RuntimeError((res.stderr or res.stdout).strip()[-400:])
